This makes it easy to select a bone in the inspector:

```gdscript
@export var bone_name: String = "":
    set(bn):
        bone_name = bn
        var skeleton := get_skeleton()
        bone_idx = skeleton.find_bone(bone_name)

func _get_property_list():
    var properties = []

    var skeleton := get_skeleton()
    if skeleton is Skeleton3D:
        var bone_names = skeleton.get_bone_count()
        var bone_enum = PackedStringArray()
        for i in range(bone_names):
            bone_enum.append(skeleton.get_bone_name(i))

        properties.append({
            "name": "bone_name",
            "type": TYPE_STRING,
            "hint": PROPERTY_HINT_ENUM,
            "hint_string": ",".join(bone_enum),
            "usage": PROPERTY_USAGE_DEFAULT
        })

    return properties
